def add(cat,id,title,level,source,goal,do,code,expected=None,stdin='',hint='',why='',quiz=None,trace=None,conceal=False):
 lessons.append(dict(cat=cat,id=id,title=title,level=level,source=source,goal=goal,do=do,code=code,expected=expected,stdin=stdin,hint=hint,why=why,quiz=quiz or [],trace=trace or [],conceal=conceal))
