add('basic','b01','まずは実行してみよう','見る→実行','p.70 順次構造','プログラムは上から順番に動く。','まず「実行」してみよう。そのあと、好きな文字に書き換えてもう一度実行。',"print('こんにちは')\nprint('情報Ⅰ')",'こんにちは\n情報Ⅰ',hint='print() は文字や数字を表示する関数。文字は引用符で囲もう。',why='順次構造：1行目が終わってから2行目が実行される。')
add('basic','b02','変数は値を入れる箱','数字を変更','p.70 変数','変数と代入の意味を知る。','まず実行し、次に x を 12 に変えて「12」が表示されるようにしよう。','x = 5\nprint(x)','12',hint='1行目の 5 を 12 に変更。',why='「x = 12」は、数学の等号ではなく「変数 x に12を代入する」という意味。')
add('basic','b03','変数の値を更新する','1行を書き換え','p.70 変数','自分自身に足す処理を理解する。','「x = x + 3」の3を変更し、結果を 15 にしよう。','x = 8\nx = x + 3\nprint(x)','15',hint='8 に 7 を足すと15。',why='右辺を先に計算し、結果を左辺の変数に入れる。')
add('basic','b04','商と余りを使う','実行→考える','p.75 / 問106への準備','//（商）と %（余り）の違い。','まず実行。次に 23円を10円硬貨と1円硬貨に分けるように、xを23に変更しよう。','x = 17\nprint(x // 10)\nprint(x % 10)','2\n3',hint='23 // 10 は 2、23 % 10 は 3。',why='// は割り算の商の整数部分（正の整数で考える）。% は割った余り。',trace=['23 ÷ 10 → 商2、余り3','10円硬貨2枚、残り3円 → 1円硬貨3枚'])
add('basic','b05','小さな計算を組み立てる','チャレンジ','p.75 / 問106への準備','商を使って50円硬貨の枚数を求める。','x = 347円 のとき、50円硬貨が6枚と表示されるように「// 10」を修正しよう。','x = 347\nnum50 = x // 10\nprint(num50)','6',hint='50円硬貨の枚数 → 347 // 50。',why='50円硬貨は 347 ÷ 50 の商の整数部分で6枚。余りは47円。')

add('branch','c01','条件が成り立つときだけ','数字を変更','p.71 選択構造','if と else の分岐。','xを20に変更し、「成人」が表示されるようにしよう。','x = 15\nif x >= 18:\n    print("成人")\nelse:\n    print("18歳未満")','成人',hint='最初の x = 15 を x = 20 に。',why='条件式がTrueならifの下、そうでなければelseの下を実行する。')
add('branch','c02','余りで偶数かを判断','条件式を変更','p.71 例題55 / p.75 問105⑴','% と == を組み合わせる。','偶数のときだけ「Yes」が出るよう、ifの条件を直そう。',"x = int(input('整数を入力: '))\nif x % 3 == 0:\n    print('Yes')\nelse:\n    print('No')",'Yes','10',hint='偶数は2で割った余りが0。% 3 を % 2 に変えよう。',why='== は比較（等しいか）、= は代入。12 % 2 == 0 はTrue。',quiz=[Q('ベストフィット105⑴：このプログラムは何を判断する？',['正か負か','偶数か奇数か','3桁かどうか'],'偶数か奇数か')])
add('branch','c03','FIZZとBUZZ（入れ子）','実行→予想','p.71 例題55','字下げされた処理の範囲。','最初は x=30 で実行。次に x=9 にして、FIZZだけが表示されることを確認。',"x = 30\nif x % 3 == 0:\n    print('FIZZ')\n    if x % 5 == 0:\n        print('BUZZ')",'FIZZ\nBUZZ',hint='x が3の倍数か確認してから、さらに5の倍数か確認する。',why='内側の if は、外側の if が成立した場合だけ実行される。x=9ではFIZZだけ。',quiz=[Q('x=10 に変えると何が表示される？',['FIZZ','BUZZ','何も表示されない'],'何も表示されない')])
add('branch','c04','絶対値を求めよう','条件を書き換え','p.72 / 問100','負数の符号を反転する。','-8 を 8 と表示するように「if x > 0:」を修正しよう。','x = -8\nif x > 0:\n    x = -x\nprint(x)','8',hint='x が0より小さいとき符号を反転：x < 0',why='-(-8) = 8。0以上の値は変更する必要がない。')
add('branch','c05','映画館の料金を決める','コードを読む','p.72 / 問99','複数分岐 elif の使い方。','25歳の料金を確認してみよう。次に x=16、x=65でも試してみよう。','x = 25\nif x <= 18:\n    print(1000)\nelif x >= 60:\n    print(1200)\nelse:\n    print(1800)','1800',hint='25歳は「18歳以下」でも「60歳以上」でもない。',why='p.72のフローチャートと同じで、19〜59歳は1800円。',quiz=[Q('x=65なら料金は？',['1000円','1200円','1800円'],'1200円')])

add('loop','l01','同じ処理を何回も','数字を変更','p.71 反復構造','range(n) が0からn-1まで回す。','3回の表示を5回にするよう、range(3)を書き換えよう。',"for i in range(3):\n    print('こんにちは')",'こんにちは\nこんにちは\nこんにちは\nこんにちは\nこんにちは',hint='range(5) は i=0,1,2,3,4 の5回。',why='for行の下で字下げされたprintが5回実行される。')
add('loop','l02','インデントで表示回数が変わる','実行→選ぶ','p.72 例題56','printの字下げと繰り返し。','まず1回だけ5と表示されることを確認。その後print(x)を4つ空白で字下げするとどうなる？','x = 0\nfor i in range(5):\n    x = x + 1\nprint(x)','5',hint='printがforと同じ位置ならループの外。',why='x=x+1だけが5回。print(x)は最後に1回だけ。',quiz=[Q('print(x)を4文字下げると表示は何回？',['1回','5回','6回'],'5回')],trace=['繰り返し後のx：0→1→2→3→4→5','ループの外にある print(x) は1度だけ'])
add('loop','l03','0から順に足してみよう','数字を修正','p.72 例題56','iが0〜4に変わることを知る。','0、1、3、6、10の順に表示するため、x = x + 1 を修正しよう。','x = 0\nfor i in range(5):\n    x = x + 1\n    print(x)','0\n1\n3\n6\n10',hint='毎回1を足すのではなく、変数 i を足す。',why='iは0→1→2→3→4。累積和は0→1→3→6→10。',trace=['i=0 → x=0','i=1 → x=1','i=2 → x=3','i=3 → x=6','i=4 → x=10'])
add('loop','l04','1から入力値までの和','数値を変更','p.75 / 問105⑶','range(1, x+1) で1〜x。','1〜10の和55を表示しよう。入力欄の「5」を「10」に変えて実行。',"x = int(input('正の整数: '))\nkekka = 0\nfor i in range(1, x + 1):\n    kekka = kekka + i\nprint(kekka)",'55','5',hint='コードではなく下の「入力値」欄を10に変更する。',why='rangeの終点は含まれないため、x+1にするとxまで足せる。',quiz=[Q('問105⑶：何をするプログラム？',['入力値までの合計を求める','入力値の約数を出す','入力値を2乗する'],'入力値までの合計を求める')])
add('loop','l05','約数を全部表示する','実行→選ぶ','p.75 / 問105⑷','繰り返しと条件分岐の組合せ。','入力12で実行し、約数を確かめよう。続いて入力6などでも試してみよう。',"x = int(input('正の整数: '))\nretsu = []\nfor i in range(1, x + 1):\n    if x % i == 0:\n        retsu.append(i)\nprint(retsu)",'[1, 2, 3, 4, 6, 12]','12',hint='x % i == 0 なら割り切れる → iをリストへ追加する。',why='retsu.append(i)はリストの最後にiを追加する。',quiz=[Q('問105⑷：どんな数がリストに入る？',['xより大きい数','xの約数','偶数だけ'],'xの約数')])
add('loop','l06','複利を1年ずつ計算','コードを読む','p.73 / 問101への準備','預金額に1.01を繰り返しかける。','10000円を年1%で3年間増やした推移を確認しよう。',"yokin = 10000\nrisoku = 1.0\nfor i in range(3):\n    yokin = yokin * (1 + risoku / 100)\n    print(int(yokin))",'10100\n10201\n10303',hint='1年目10100、2年目10201、3年目10303（小数点以下切捨て）。',why='利率は一定1%。増えるのは預金額。int()は小数部分を切り捨てる。',trace=['1年目：10000×1.01＝10100','2年目：10100×1.01＝10201','3年目：10201×1.01＝10303.01 → 表示は10303'])
add('loop','l07','★ ベストフィット 101','教科書に挑戦','p.73 問101','複利の10年分の表示について正しく説明する。','最初に正しい説明を選び、その後「実行」して本当に10行表示されるか確かめよう。',"yokin = 10000\nrisoku = 1.0\nfor i in range(10):\n    yokin = yokin * (1 + risoku / 100)\n    print(int(yokin))",'10100\n10201\n10303\n10406\n10510\n10615\n10721\n10828\n10936\n11046',hint='print() の位置は、for文の下で字下げされている。',why='正答は(エ)。表示処理も10回繰り返され、利率は1%のまま。',quiz=[Q('問101：最も適当な記述はどれ？',['(ア) 利息は毎年100分の1ずつ増加','(イ) 預金額に年数は関係ない','(ウ) 計算後に一度だけ表示','(エ) 年数分繰り返し表示'],'(エ) 年数分繰り返し表示')],conceal=True)

add('array','a01','配列に並んだデータ','数字を変更','p.71 配列','添字が0から始まる。','2番目の得点「40」を表示するよう [0] を変えよう。','Tokuten = [50, 40, 90]\nprint(Tokuten[0])','40',hint='Pythonは0番目から数えるので、2番目は添字[1]。',why='配列の位置を表す数字が「添字」。Pythonの先頭は添字0。')
add('array','a02','配列を順に取り出す','実行→選ぶ','p.72 例題57','for x in 配列 を理解する。','まず実行して、配列の要素が順番に表示されることを確かめよう。','kakaku = [580, 970, 430]\nfor x in kakaku:\n    print(x)','580\n970\n430',hint='xに580→970→430と順番に入る。',why='for x in kakaku は配列のすべての要素を一つずつ取り出す。',quiz=[Q('このfor文は何回繰り返される？',['2回','3回','4回'],'3回')])
add('array','a03','いちばん安い値を探す','条件を変更','p.72 例題57','小さい数が見つかれば最小値を更新。','最安値430と表示されるよう if の比較演算子を修正しよう。',"kakaku = [580, 970, 430, 820, 760]\nsaisyo = kakaku[0]\nfor x in kakaku:\n    if x > saisyo:\n        saisyo = x\nprint('最安値:', saisyo)",'最安値: 430',hint='最小値を探すので x < saisyo とする。',why='現在の最小値と順番に比較し、より小さいときだけ更新する。',trace=['初期値 saisyo=580','970：更新しない','430：430に更新','820,760：更新しない →430'])
add('array','a04','最高点と出席番号','実行→理解','p.74 / 問102への準備','最高点と位置を一緒に記録する。','4人分の最高点と出席番号を表示してみよう。',"Tokuten = [50, 40, 90, 70]\nsaidai = 0\nbango = 0\nfor i in range(len(Tokuten)):\n    if Tokuten[i] > saidai:\n        saidai = Tokuten[i]\n        bango = i\nprint('最高点：', saidai, '出席番号：', bango + 1)",'最高点： 90 出席番号： 3',hint='最大値saidaiを変えるとき、添字bangoも一緒に更新。',why='Pythonの添字は0開始。出席番号は1開始なので表示時にbango+1とする。',trace=['i=0：50 → saidai=50、bango=0','i=1：40 → 更新なし','i=2：90 → saidai=90、bango=2','i=3：70 → 更新なし、出席番号3'])
add('array','a05','★ ベストフィット 102','教科書に挑戦','p.74 問102','教科書（添字1開始）の穴埋めを解ける。','教科書の空欄①②③を答えよう。その後、Pythonで同じ処理を実行して違いを確かめる。',"# Python版：添字は0から始まる\nTokuten = [50, 40, 95, 30, 70]\nsaidai = 0\nbango = 0\nfor i in range(len(Tokuten)):\n    if Tokuten[i] > saidai:\n        saidai = Tokuten[i]\n        bango = i\nprint('最高点：', saidai, '出席番号：', bango + 1)",'最高点： 95 出席番号： 3',hint='教科書は添字1開始。①は要素数、②は大きければ更新、③は出席番号を記録した変数。',why='解答：①(ア)要素数(Tokuten)、②(オ)>、③(ク)bango。Pythonは添字0開始なので range(len(...))、表示はbango+1。',quiz=[Q('① 繰り返しの最後の添字（教科書：1開始）',['(ア) 要素数(Tokuten)','(イ) 要素数(Tokuten)-1','(ウ) 要素数(Tokuten)+1'],'(ア) 要素数(Tokuten)'),Q('② 最高点を更新する比較演算子',['(エ) <','(オ) >','(カ) =='],'(オ) >'),Q('③ 出席番号として表示するもの（教科書）',['(キ) i','(ク) bango','(ケ) bango + 1'],'(ク) bango')],conceal=True)

add('matrix','m01','縦横に並ぶ二次元配列','数字を変更','p.72 例題58','二つの添字を読める。','「33」を表示できるように最後の [0][1] を直そう。','a = [[1, 2, 3], [11, 22, 33]]\nprint(a[0][1])','33',hint='2行目の3番目。添字は[1][2]。',why='a[行][列]の順で指定する。0始まりなので2行目は[1]、3列目は[2]。')
add('matrix','m02','配列の月と日を読み取る','実行→選ぶ','p.72 例題58','kousui[2][8]の場所を理解する。','まず実行してから、何月何日を表すか考えよう。',"kousui = [[0] * 31 for _ in range(12)]\nkousui[2][8] = 12\nprint(kousui[2][8])",'12',hint='月も日も0から数えている。2は3番目の月、8は9番目の日。',why='例題58の答えは3月9日。値12はこの教材で置いた仮の降水量。',quiz=[Q('kousui[2][8]は何月何日？',['2月8日','3月8日','3月9日'],'3月9日')])
add('matrix','m03','二重の繰り返しで九九','数字を変更','p.74 / 問103への準備','外側のdanと内側のkazu。','2の段を1行出したら、外側のrange(2,3)をrange(2,4)に変えて、3の段まで表示しよう。','for dan in range(2, 3):\n    for kazu in range(1, 4):\n        print(dan * kazu, end=" ")\n    print()','2 4 6 \n3 6 9 ',hint='外側ループは段。range(2,4)ならdan=2,3。',why='内側のループが終わるたびに print() で改行して、段を分ける。')
add('matrix','m04','★ ベストフィット 103','教科書に挑戦','p.74 問103','1段分を9回表示できる。','教科書の空欄①と、配列表示()に渡す引数を答えよう。次にPythonの9×9の表を実行。','Kuku = [[0] * 9 for _ in range(9)]\nfor dan in range(1, 10):\n    for kazu in range(1, 10):\n        Kuku[dan - 1][kazu - 1] = dan * kazu\n    print(Kuku[dan - 1])', '\n'.join(str([dan*k for k in range(1,10)]) for dan in range(1,10)),hint='(04)で九九の数を代入後、(05)は「内側forの外、外側forの中」に置く。',why='⑴03行目と揃えると、kaz uのループ終了後に段ごと表示（答え03）。⑵(イ)Kuku[dan]。Pythonの二次元配列は0開始なので[dan-1]。'.replace('kaz u','kazu'),quiz=[F('⑴ 空欄①に入る行番号（半角数字2桁）','03'),Q('⑵ 配列表示() に渡すもの（教科書）',['(ア) Kuku','(イ) Kuku[dan]','(ウ) Kuku[kazu]','(エ) Kuku[dan][kazu]'],'(イ) Kuku[dan]')],conceal=True,trace=['dan=1: 1の段を9個代入→1行表示','dan=2: 2の段を9個代入→1行表示','…','dan=9: 9の段を9個代入→1行表示（計9行）'])

add('function','f01','関数は処理のひとまとめ','実行→変える','p.71 関数','defと関数の呼び出し。','printの文字を「おはよう」に変更し、関数から表示させよう。',"def aisatsu():\n    print('こんにちは')\naisatsu()",'おはよう',hint='defの下の文字列を変更。',why='defで関数を定義するだけでは動かない。aisatsu()と呼び出して初めて実行する。')
add('function','f02','関数に値を渡す','数値を変更','p.71 三角形の面積','引数の働き。','底辺8、高さ4の面積16になるよう、関数を呼び出すときの数字を修正しよう。','def sankaku(teihen, takasa):\n    return teihen * takasa / 2\nprint(sankaku(8, 2))','16.0',hint='sankaku(8,4)にすると8×4÷2=16。',why='teihen、takasaは引数。returnで呼び出し元へ計算結果を返す。')
add('function','f03','税込価格を関数で求める','数字を変更','p.72 例題59','同じ関数を別の引数で使える。','1980円の10%・8%税込価格が表示されるように、2回目の税率を修正しよう。','def zeikomi(kingaku, tax):\n    return kingaku + kingaku * tax // 100\nkakaku = 1980\nprint(zeikomi(kakaku, 10))\nprint(zeikomi(kakaku, 10))','2178\n2138',hint='2回目の関数呼び出しの 10 を 8 にする。',why='関数は何度でも呼び出せる。引数を変えれば結果も変わる。')
add('function','f04','return と print は違う','コードを読む','p.74 / 問104への準備','戻り値と表示の区別。','半径2の円の面積を表示しよう。returnの結果がprintに渡る。','def func(kazu):\n    pai = 3.14\n    return pai * kazu * kazu\nprint(func(2))','12.56',hint='3.14 × 2 × 2 = 12.56。',why='returnは「値を返す」処理。画面に表示しているのは関数の外のprint。')
add('function','f05','★ ベストフィット 104','教科書に挑戦','p.74 問104','関数の戻り値を予想できる。','x=5を入力すると「答えは」の後に何が表示される？ 予想を回答してから実行しよう。',"def func(kazu):\n    pai = 3.14\n    return pai * kazu * kazu\nx = float(input('正の数を入力: '))\nprint('答えは', func(x))",'答えは 78.5','5',hint='3.14 × 5 × 5 = 78.5。',why='引数kazuに5.0が渡され、returnで78.5が返される。',quiz=[F('「答えは」の直後に表示される数値','78.5')],conceal=True)

add('integrated','i01','3桁の数字を逆さに','コードを読む','p.75 / 問105⑵','// と % を組み合わせる。','入力123を321にして表示する処理を確認。次に456も試してみよう。',"x = int(input('3桁の整数: '))\nn100 = x // 100\nn10 = (x % 100) // 10\nn1 = x % 10\nprint(n1 * 100 + n10 * 10 + n100)",'321','123',hint='123の百の位は1、十の位は2、一の位は3。3×100+2×10+1。',why='問105⑵：入力された3桁の数字の並びを逆順にして表示。',quiz=[Q('問105⑵：このプログラムは何をする？',['3桁を逆に並べる','3桁の合計を求める','3桁かどうか判定する'],'3桁を逆に並べる')],trace=['123 // 100 → 1','(123 % 100) // 10 → 2','123 % 10 → 3','3×100+2×10+1 → 321'])
add('integrated','i02','50円で何枚払える？','数値を書き換え','p.75 / 問106への準備','大きい硬貨から先に考える。','347円に対し50円硬貨が6枚、残りが47円になるよう修正しよう。','x = 347\nnum50 = x // 10\nnokori = x - num50 * 50\nprint(num50)\nprint(nokori)','6\n47',hint='50円硬貨の枚数は347 // 50。',why='大きい硬貨から決める。347−6×50＝47。')
add('integrated','i03','10円・1円も計算','1行を書き換え','p.75 / 問106への準備','残金を使った硬貨の枚数。','50円6枚、10円4枚、1円7枚、合計17枚を表示するように10円硬貨の式を直そう。',"x = 347\nnum50 = x // 50\nnum10 = (x - num50 * 50) // 50\nnum1 = x - num50 * 50 - num10 * 10\nprint(num50, num10, num1)\nprint(num50 + num10 + num1)",'6 4 7\n17',hint='num10の計算では、残った金額を10で割る。',why='347円＝50円×6＋10円×4＋1円×7。6+4+7=17枚。',trace=['347//50 → 6枚、残り47円','47//10 → 4枚、残り7円','1円7枚、合計6+4+7=17枚'])
add('integrated','i04','★ ベストフィット 106','教科書に挑戦','p.75 問106','硬貨の最小枚数を求める5つの空欄。','教科書の空欄①〜⑤（いずれも数字）を答えて、347円の例で実行しよう。',"x = int(input('代金を入力: '))\nnum50 = x // 50\nnum10 = (x - num50 * 50) // 10\nnum1 = x - num50 * 50 - num10 * 10\nprint('最小限の枚数は', num50 + num10 + num1, '枚')",'最小限の枚数は 17 枚','347',hint='まず50円の枚数→残金の10円の枚数→残りの1円の枚数。',why='解答：①50、②50、③10、④50、⑤10。347円なら6+4+7=17枚。',quiz=[F('① 50円硬貨の枚数を求める除数','50'),F('② 50円硬貨の金額として掛ける数','50'),F('③ 10円硬貨の枚数を求める除数','10'),F('④ 50円硬貨の合計金額の単価','50'),F('⑤ 10円硬貨の合計金額の単価','10')],conceal=True)
add('integrated','i05','★ ベストフィット 105 総まとめ','教科書に挑戦','p.75 問105⑴〜⑷','4つのプログラムを説明できる。','101〜106の総仕上げ。4つの処理の役割を選び、それぞれの実行結果と一致するか確認しよう。',"# 問105⑴〜⑷は他のページで実際に実行できます\n# ここでは4つの動きをまとめて確認します\nprint('⑴', 12 % 2 == 0)\nprint('⑵', 3 * 100 + 2 * 10 + 1)\nprint('⑶', sum(range(1, 6)))\nprint('⑷', [i for i in range(1, 13) if 12 % i == 0])",'⑴ True\n⑵ 321\n⑶ 15\n⑷ [1, 2, 3, 4, 6, 12]',hint='⑴偶数、⑵3桁逆順、⑶1〜xの和、⑷約数。',why='問105の各サンプルの詳細は「条件分岐」「繰り返し」「総合演習」で学べる。',quiz=[Q('⑴ x%2==0 の役割',['偶数か判断','約数を表示','絶対値を表示'],'偶数か判断'),Q('⑵ 位を取り出す処理',['値を3倍する','3桁を逆順にする','百の位だけ表示'],'3桁を逆順にする'),Q('⑶ 1からxまで繰り返す処理',['合計を求める','最大値を求める','倍数だけ求める'],'合計を求める'),Q('⑷ x%i==0 でリストに追加',['平方根','約数','素数だけ'],'約数')],conceal=True)

